// An email to the agency inbox becomes the common inbound message: the new text only (quoted
// history and signature cut), with the subject when it starts a conversation. The person is keyed
// by their address; replies go back into the same Gmail thread.
const profile = $('Config').first().json.profile;
const out = [];
for (const item of $('New email').all()) {
  const m = item.json;
  const from = m.from?.value?.[0] ?? {};
  const address = String(from.address ?? '').toLowerCase();
  const subject = String(m.subject ?? '').trim();
  // Automatic mail is not a lead.
  // "noreply@", and also "noreply-accounts@", "no_reply.alerts@" and the like.
  if (!address || /^(no[-_.]?reply|do[-_.]?not[-_.]?reply|mailer-daemon|postmaster|notifications?)([-_.+][^@]*)?@/i.test(address)) continue;
  if (/^(automatic reply|auto(matic)?[- ]?reply|out of (the )?office|undeliverable|delivery status)/i.test(subject)) continue;
  const raw = String(m.text ?? '').trim() || String(m.html ?? '').replace(/<[^>]+>/g, ' ').replace(/[ \t]+/g, ' ').trim();
  const kept = [];
  const lines = raw.replace(/\r/g, '').split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line === '--' || line === '-- ' || /^-{2,}\s*Original Message/i.test(line)) break;
    if (/^On .+/.test(line) && /wrote:\s*$/.test(`${line} ${lines[i + 1] ?? ''}`)) break;
    if (/^From: /.test(line) && kept.length) break;
    if (line.startsWith('>')) continue;
    kept.push(lines[i]);
  }
  const textBody = kept.join('\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);
  const startsThread = !/^(re|fwd?):/i.test(subject);
  const text = startsThread && subject ? `Subject: ${subject}\n\n${textBody}` : textBody;
  if (!text) continue;
  out.push({ json: {
    profile,
    channel: 'email',
    external_user_id: address,
    external_message_id: m.id,
    sent_at: m.date ? new Date(m.date).toISOString() : new Date().toISOString(),
    text,
    attachments: (m.attachments ?? []).map((a) => ({ type: 'file', name: a.filename ?? null })),
    sender: { display_name: from.name || null, username: null, phone: null, email: address },
    address: { email: address, thread_id: m.threadId, subject: subject.replace(/^(re|fwd?):\s*/i, '') },
  } });
}
return out;
